package com.notificationservice.infrastructure.external;
import com.cloudinary.Cloudinary; import com.cloudinary.utils.ObjectUtils; import com.notificationservice.application.port.out.SupportImageStorage; import com.notificationservice.infrastructure.config.CloudinarySupportConfiguration.Properties; import org.springframework.stereotype.Component; import java.util.*;
@Component public class CloudinarySupportImageStorage implements SupportImageStorage { private final Cloudinary cloudinary; private final Properties properties; public CloudinarySupportImageStorage(Cloudinary c,Properties p){cloudinary=c;properties=p;}
 public StoredImage upload(byte[] bytes,String filename,String contentType,long size){if(!properties.configured())throw new IllegalArgumentException("Image storage is not configured"); try{Map<?,?> r=cloudinary.uploader().upload(bytes,ObjectUtils.asMap("folder","hau-qm/support-chat","resource_type","image","use_filename",false,"unique_filename",true));Object url=r.get("secure_url");if(url==null)url=r.get("url");return new StoredImage(String.valueOf(url),String.valueOf(r.get("public_id")));}catch(Exception e){throw new IllegalArgumentException("Could not upload support image",e);}}
}
